//go:build ebpf

package network

import _ "embed"

// embeddedDataplaneELF contains the compiled multi-program BPF ELF object.
// Generated by scripts/build-ebpf.sh from network/ebpf/cca_dataplane.c.
// All BPF programs (socket LB, tc DNAT, tc SNAT) and shared maps are in
// this single ELF, eliminating the need for /usr/lib/cca/*.o on disk.
//
//go:embed ebpf/cca_dataplane.o
var embeddedDataplaneELF []byte
